import re

def validate_tags(tags):
    # Ensure tags only contain alphanumeric characters and commas, and are not empty
    if not tags:
        return False
    # Use regex to allow only alphanumeric characters and commas
    return bool(re.match(r'^[a-zA-Z0-9,]+$', tags))

